from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise SystemExit(f"missing patch anchor: {label}")
    return text.replace(old, new, 1)


# 1) Product configuration: adult generation is strictly Krea -> Seedream.
config_path = Path("app/core/config.py")
config = config_path.read_text(encoding="utf-8")
config = replace_once(
    config,
    '''    image_generation_adult_fallback_model: str = "lustify-sdxl"\n    image_generation_adult_emergency_models: str = "lustify-v8"\n    image_generation_adult_max_generation_attempts: int = 4\n''',
    '''    # Adult generation is intentionally restricted to Venice's uncensored\n    # Krea primary and Seedream fallback. Runtime code enforces this order even\n    # when an older deployment environment still contains Lustify/SD/Z models.\n    image_generation_adult_fallback_model: str = "seedream-v5-lite"\n    image_generation_adult_emergency_models: str = ""\n    image_generation_adult_max_generation_attempts: int = 3\n''',
    "adult generation config",
)
config_path.write_text(config, encoding="utf-8")


# 2) Worker model policy and stable Krea identity seed.
service_path = Path("app/services/image_generation_service.py")
service = service_path.read_text(encoding="utf-8")
old_plan = '''def _split_configured_models(value: object) -> list[str]:\n    return [part.strip() for part in str(value or '').split(',') if part.strip()]\n\n\ndef build_generation_model_plan(settings, primary_model: str, *, adult_generation: bool) -> list[str]:\n    if adult_generation:\n        candidates = [\n            getattr(settings, 'image_generation_adult_preferred_model', None),\n            primary_model,\n            getattr(settings, 'image_generation_adult_model', None),\n            getattr(settings, 'image_generation_adult_fallback_model', None),\n            *_split_configured_models(getattr(settings, 'image_generation_adult_emergency_models', '')),\n        ]\n    else:\n        candidates = [\n            getattr(settings, 'image_generation_preferred_model', None),\n            primary_model,\n            getattr(settings, 'image_generation_model', None),\n            getattr(settings, 'image_generation_fallback_model', None),\n            *_split_configured_models(getattr(settings, 'image_generation_emergency_models', '')),\n        ]\n    plan: list[str] = []\n    for candidate in candidates:\n        model = str(candidate or '').strip()\n        if model and model not in plan:\n            plan.append(model)\n    return plan\n\n\ndef build_generation_attempt_plan(model_plan: list[str], *, adult_generation: bool, max_attempts: int) -> list[tuple[str, int]]:\n    attempts: list[tuple[str, int]] = []\n    for index, model in enumerate(model_plan):\n        attempts.append((model, 0))\n        # Adult full-body requests get one same-model corrective retry before\n        # falling back. This is the missing retry that previously refunded after\n        # the first cropped Krea/Lustify candidate.\n        if adult_generation and index == 0:\n            attempts.append((model, 1))\n    return attempts[: max(1, int(max_attempts))]\n'''
new_plan = '''def _split_configured_models(value: object) -> list[str]:\n    return [part.strip() for part in str(value or '').split(',') if part.strip()]\n\n\nADULT_PRIMARY_GENERATION_MODEL = 'krea-2-turbo'\nADULT_FALLBACK_GENERATION_MODEL = 'seedream-v5-lite'\nADULT_ALLOWED_GENERATION_MODELS = (\n    ADULT_PRIMARY_GENERATION_MODEL,\n    ADULT_FALLBACK_GENERATION_MODEL,\n)\n\n\ndef build_generation_model_plan(settings, primary_model: str, *, adult_generation: bool) -> list[str]:\n    if adult_generation:\n        # Product contract: explicit-adult images use only Krea and then Seedream.\n        # Ignore stale environment values so Lustify/SD/Z-image can never leak\n        # back into this route. Availability filtering happens in the worker.\n        return list(ADULT_ALLOWED_GENERATION_MODELS)\n    candidates = [\n        getattr(settings, 'image_generation_preferred_model', None),\n        primary_model,\n        getattr(settings, 'image_generation_model', None),\n        getattr(settings, 'image_generation_fallback_model', None),\n        *_split_configured_models(getattr(settings, 'image_generation_emergency_models', '')),\n    ]\n    plan: list[str] = []\n    for candidate in candidates:\n        model = str(candidate or '').strip()\n        if model and model not in plan:\n            plan.append(model)\n    return plan\n\n\ndef build_generation_attempt_plan(model_plan: list[str], *, adult_generation: bool, max_attempts: int) -> list[tuple[str, int]]:\n    attempts: list[tuple[str, int]] = []\n    for model in model_plan:\n        attempts.append((model, 0))\n        # Only Krea gets one composition-only retry. Seedream is the final\n        # fallback and is never silently repeated or followed by another model.\n        if adult_generation and model == ADULT_PRIMARY_GENERATION_MODEL:\n            attempts.append((model, 1))\n    return attempts[: max(1, int(max_attempts))]\n'''
service = replace_once(service, old_plan, new_plan, "generation model/attempt policy")
service = replace_once(
    service,
    "            fallback_model = ((getattr(settings, 'image_generation_adult_fallback_model', '') if adult_generation else getattr(settings, 'image_generation_fallback_model', '')) or '').strip()\n",
    "            fallback_model = (ADULT_FALLBACK_GENERATION_MODEL if adult_generation else (getattr(settings, 'image_generation_fallback_model', '') or '').strip())\n",
    "fallback metadata model",
)
service = replace_once(
    service,
    "            max_model_count = 3 if adult_generation else 2\n",
    "            max_model_count = 2\n",
    "adult max model count",
)
service = replace_once(
    service,
    "            max_generation_attempts = int(getattr(settings, 'image_generation_adult_max_generation_attempts', 4) or 4) if adult_generation else len(model_plan)\n",
    "            max_generation_attempts = int(getattr(settings, 'image_generation_adult_max_generation_attempts', 3) or 3) if adult_generation else len(model_plan)\n",
    "adult max attempts",
)
old_seed_loop = '''            accepted_qa=None\n            for attempt_index, (attempt_model, correction_round) in enumerate(attempt_plan):\n                # A corrective repeat is meaningful only after the same model\n                # produced a real image that QA rejected. Provider errors and\n                # moderation cards move directly to the next available model.\n                if correction_round and (not rejected_quality or rejected_quality[-1].get('model') != attempt_model):\n                    continue\n                seed_source = job.seed if attempt_index == 0 else deterministic_provider_seed(\n                    job.seed, job.id, attempt_model, correction_round, attempt_index,\n                    ','.join(rejected_quality[-1].get('reason_codes') or []) if rejected_quality else 'provider-fallback',\n                )\n                attempt_seed, norm_applied = normalize_venice_seed(seed_source, salt=f'job:{job.id}:{attempt_model}:{correction_round}:{attempt_index}')\n                job.metadata_json={**(job.metadata_json or {}),'normalized_provider_seed':attempt_seed,'seed_normalization_applied': bool((job.metadata_json or {}).get('seed_normalization_applied') or norm_applied),'seed_provider_min':VENICE_SEED_MIN,'seed_provider_max':VENICE_SEED_MAX}\n                attempt_prompt=(job.prompt or '') + (corrective_prompt_for_reasons(rejected_quality[-1]['reason_codes'], expected_subject_count=int((job.metadata_json or {}).get('expected_subject_count', 1)), expected_interaction=(job.metadata_json or {}).get('interaction'), secondary_subject_role=(job.metadata_json or {}).get('secondary_subject_role'), identity_requirements=(job.metadata_json or {}).get('identity_descriptor'), photo_contract=((job.metadata_json or {}).get('visual_requirements') or {}).get('photo_contract')) if rejected_quality and attempt_index > 0 else '')\n'''
new_seed_loop = '''            accepted_qa=None\n            stable_krea_seed=None\n            stable_krea_norm_applied=False\n            if adult_generation and ADULT_PRIMARY_GENERATION_MODEL in model_plan:\n                stable_krea_seed, stable_krea_norm_applied = normalize_venice_seed(\n                    job.seed,\n                    salt=f'job:{job.id}:{ADULT_PRIMARY_GENERATION_MODEL}:identity',\n                )\n            for attempt_index, (attempt_model, correction_round) in enumerate(attempt_plan):\n                # A corrective repeat is meaningful only after the same model\n                # produced a real image that QA rejected. Provider errors and\n                # moderation cards move directly to Seedream.\n                if correction_round and (not rejected_quality or rejected_quality[-1].get('model') != attempt_model):\n                    continue\n                if adult_generation and attempt_model == ADULT_PRIMARY_GENERATION_MODEL:\n                    # Keep the exact numeric Krea seed across its base and\n                    # composition-correction attempts. Only framing instructions\n                    # may change; identity seed/family must not drift.\n                    attempt_seed = stable_krea_seed\n                    norm_applied = stable_krea_norm_applied\n                else:\n                    seed_source = job.seed if attempt_index == 0 else deterministic_provider_seed(\n                        job.seed, job.id, attempt_model, correction_round, attempt_index,\n                        ','.join(rejected_quality[-1].get('reason_codes') or []) if rejected_quality else 'provider-fallback',\n                    )\n                    attempt_seed, norm_applied = normalize_venice_seed(\n                        seed_source,\n                        salt=f'job:{job.id}:{attempt_model}:{correction_round}:{attempt_index}',\n                    )\n                job.metadata_json={**(job.metadata_json or {}),'normalized_provider_seed':attempt_seed,'stable_krea_identity_seed':stable_krea_seed,'seed_normalization_applied': bool((job.metadata_json or {}).get('seed_normalization_applied') or norm_applied),'seed_provider_min':VENICE_SEED_MIN,'seed_provider_max':VENICE_SEED_MAX}\n                correction_required=bool(\n                    rejected_quality\n                    and (correction_round or attempt_model == ADULT_FALLBACK_GENERATION_MODEL)\n                )\n                attempt_prompt=(job.prompt or '') + (corrective_prompt_for_reasons(rejected_quality[-1]['reason_codes'], expected_subject_count=int((job.metadata_json or {}).get('expected_subject_count', 1)), expected_interaction=(job.metadata_json or {}).get('interaction'), secondary_subject_role=(job.metadata_json or {}).get('secondary_subject_role'), identity_requirements=(job.metadata_json or {}).get('identity_descriptor'), photo_contract=((job.metadata_json or {}).get('visual_requirements') or {}).get('photo_contract')) if correction_required else '')\n'''
service = replace_once(service, old_seed_loop, new_seed_loop, "stable Krea seed loop")
service_path.write_text(service, encoding="utf-8")


# 3) Every corrective retry preserves identity and changes composition only.
qa_path = Path("app/services/generated_image_qa_service.py")
qa = qa_path.read_text(encoding="utf-8")
qa = replace_once(
    qa,
    "    if codes & {'framing_mismatch','missing_full_body','missing_feet','cropped_body','missing_head','closeup_forbidden'}:\n        lines.append('Correct the framing exactly: full body visible in a portrait 4:5 mirror composition; full figure head-to-feet and entirely inside the frame; visible headroom above the hair and visible floor below both feet; both feet fully visible; subject no more than about 70 percent of frame height; camera farther away; no close-up and no crop.')\n",
    "    if identity_requirements:\n        lines.append('Preserve the exact stored fictional identity and facial geometry. Do not change face shape, eyes, eyebrows, nose, jawline, hairline, skin tone, age appearance, body build, or distinguishing details. This retry may change only framing, camera distance, pose placement, and required scene visibility.')\n    if codes & {'framing_mismatch','missing_full_body','missing_feet','cropped_body','missing_head','closeup_forbidden'}:\n        lines.append('Correct the framing exactly: full body visible in a portrait 4:5 mirror composition; full figure head-to-feet and entirely inside the frame; visible headroom above the hair and visible floor below both feet; both feet fully visible; subject no more than about 70 percent of frame height; camera farther away; no close-up and no crop.')\n",
    "identity-only correction contract",
)
qa_path.write_text(qa, encoding="utf-8")


# 4) Permanent model-plan regression tests.
Path("tests/test_krea_adult_generation_plan.py").write_text(
    '''from types import SimpleNamespace\n\nfrom app.core.config import Settings\nfrom app.services.generated_image_qa_service import corrective_prompt_for_reasons\nfrom app.services.image_generation_guardrails import select_generation_model\nfrom app.services.image_generation_service import (\n    ADULT_ALLOWED_GENERATION_MODELS,\n    build_generation_attempt_plan,\n    build_generation_model_plan,\n)\nfrom app.services.image_pipeline_v2 import ContentClassification\n\n\ndef test_krea_is_default_and_seedream_is_only_adult_fallback():\n    settings = Settings()\n    assert settings.image_generation_adult_preferred_model == "krea-2-turbo"\n    assert settings.image_generation_adult_model == "krea-2-turbo"\n    assert settings.image_generation_adult_fallback_model == "seedream-v5-lite"\n    assert settings.image_generation_adult_emergency_models == ""\n    assert settings.image_generation_adult_max_generation_attempts == 3\n\n\ndef test_adult_model_selection_uses_krea():\n    selected = select_generation_model(\n        content_classification=ContentClassification.FULL_NUDITY,\n        default_model="krea-2-turbo",\n        adult_model="krea-2-turbo",\n    )\n    assert selected == "krea-2-turbo"\n\n\ndef test_adult_model_plan_is_strict_despite_stale_legacy_env():\n    settings = SimpleNamespace(\n        image_generation_adult_preferred_model="lustify-sdxl",\n        image_generation_adult_model="venice-sd35",\n        image_generation_adult_fallback_model="lustify-v8",\n        image_generation_adult_emergency_models="z-image-turbo,lustify-v7",\n    )\n    plan = build_generation_model_plan(\n        settings, "lustify-sdxl", adult_generation=True\n    )\n    assert plan == ["krea-2-turbo", "seedream-v5-lite"]\n    assert tuple(plan) == ADULT_ALLOWED_GENERATION_MODELS\n    assert not ({"lustify-sdxl", "lustify-v8", "venice-sd35", "z-image-turbo"} & set(plan))\n\n\ndef test_adult_attempt_plan_is_krea_same_model_retry_then_seedream():\n    assert build_generation_attempt_plan(\n        ["krea-2-turbo", "seedream-v5-lite"],\n        adult_generation=True,\n        max_attempts=3,\n    ) == [\n        ("krea-2-turbo", 0),\n        ("krea-2-turbo", 1),\n        ("seedream-v5-lite", 0),\n    ]\n\n\ndef test_full_body_correction_preserves_identity_and_changes_composition_only():\n    correction = corrective_prompt_for_reasons(\n        ["framing_mismatch", "missing_feet", "cropped_body"],\n        identity_requirements={"face": "stable fictional face"},\n        photo_contract={"camera_mode": "mirror_selfie"},\n    ).lower()\n    assert "exact stored fictional identity" in correction\n    assert "facial geometry" in correction\n    assert "may change only framing" in correction\n    assert "head-to-feet" in correction\n    assert "floor below both feet" in correction\n    assert "70 percent" in correction\n''',
    encoding="utf-8",
)


# 5) Update worker integration tests to assert stable Krea seed and Seedream fallback.
worker_path = Path("tests/test_krea_adult_worker_delivery.py")
worker = worker_path.read_text(encoding="utf-8")
worker = worker.replace('image_generation_adult_fallback_model="lustify-sdxl",', 'image_generation_adult_fallback_model="seedream-v5-lite",')
worker = worker.replace('image_generation_adult_emergency_models="lustify-v8",', 'image_generation_adult_emergency_models="",')
worker = worker.replace('image_generation_adult_max_generation_attempts=4,', 'image_generation_adult_max_generation_attempts=3,')
worker = worker.replace('return {"krea-2-turbo", "lustify-sdxl", "lustify-v8"}', 'return {"krea-2-turbo", "seedream-v5-lite", "lustify-sdxl", "lustify-v8", "venice-sd35", "z-image-turbo"}')
worker = worker.replace('class _KreaProviderFailThenLustifyClient(_KreaCropThenPassClient):', 'class _KreaProviderFailThenSeedreamClient(_KreaCropThenPassClient):')
worker = worker.replace('request_id="lustify-ok",', 'request_id="seedream-ok",')
worker = worker.replace('def test_worker_retries_krea_with_new_seed_and_correction_then_delivers(monkeypatch):', 'def test_worker_retries_krea_with_same_seed_and_identity_safe_correction_then_delivers(monkeypatch):')
worker = worker.replace('assert client.calls[0]["seed"] != client.calls[1]["seed"]', 'assert client.calls[0]["seed"] == client.calls[1]["seed"]')
worker = worker.replace('        assert "strict partner-photo correction" in second_prompt\n', '        assert "strict partner-photo correction" in second_prompt\n        assert "exact stored fictional identity" in second_prompt\n        assert "facial geometry" in second_prompt\n        assert "may change only framing" in second_prompt\n')
worker = worker.replace('client = _KreaProviderFailThenLustifyClient()', 'client = _KreaProviderFailThenSeedreamClient()')
worker = worker.replace('["krea-2-turbo", "lustify-sdxl"]', '["krea-2-turbo", "seedream-v5-lite"]')
worker = worker.replace('result.metadata_json["final_generation_model"] == "lustify-sdxl"', 'result.metadata_json["final_generation_model"] == "seedream-v5-lite"')
worker += '''\n\ndef test_two_krea_quality_failures_fall_back_only_to_seedream(monkeypatch):\n    import app.services.image_generation_service as service\n\n    async def run():\n        session = _session()\n        user = User(telegram_id=903)\n        session.add(user)\n        session.flush()\n        job = _job(session, user)\n        client = _KreaCropThenPassClient()\n        telegram = _Telegram()\n        qa_calls = 0\n\n        async def qa(*args, **kwargs):\n            nonlocal qa_calls\n            qa_calls += 1\n            if qa_calls <= 2:\n                return _qa_result(\n                    passed=False,\n                    reason_codes=["framing_mismatch", "missing_feet", "cropped_body"],\n                )\n            return _qa_result(passed=True)\n\n        async def anatomy(*args, **kwargs):\n            return _anatomy_pass()\n\n        monkeypatch.setattr(service, "get_settings", _settings)\n        monkeypatch.setattr(service, "evaluate_adult_anatomy_image", anatomy)\n        monkeypatch.setattr(\n            service.GeneratedMediaArchiveService,\n            "archive_image",\n            lambda *args, **kwargs: asyncio.sleep(0, result=False),\n        )\n\n        result = await service.process_job(\n            session,\n            job,\n            image_client=client,\n            telegram_service=telegram,\n            generated_image_qa_evaluator=qa,\n        )\n\n        assert result.status == "sent"\n        assert [call["model"] for call in client.calls] == [\n            "krea-2-turbo",\n            "krea-2-turbo",\n            "seedream-v5-lite",\n        ]\n        assert client.calls[0]["seed"] == client.calls[1]["seed"]\n        assert client.calls[2]["seed"] != client.calls[0]["seed"]\n        assert result.metadata_json["final_generation_model"] == "seedream-v5-lite"\n        assert result.metadata_json["fallback_model_used"] is True\n        assert all(\n            call["model"] not in {"lustify-sdxl", "lustify-v8", "venice-sd35", "z-image-turbo"}\n            for call in client.calls\n        )\n        assert "exact stored fictional identity" in client.calls[2]["prompt"].lower()\n        assert len(telegram.photos) == 1\n\n    asyncio.run(run())\n'''
worker_path.write_text(worker, encoding="utf-8")


# 6) Make the protected live gate exercise the same exact generation policy.
gate_path = Path("conftest.py")
gate = gate_path.read_text(encoding="utf-8")
gate = replace_once(
    gate,
    '''    model = "krea-2-turbo"\n    client = VeniceImageClient()\n    available = await client.available_image_models(ttl_seconds=30)\n    if available is not None and model not in available:\n        raise RuntimeError(\n            "LIVE_KREA_SMOKE_FAILED stage=model_discovery "\n            f"model={model} available_krea={sorted(x for x in available if 'krea' in x.lower())}"\n        )\n''',
    '''    models = ["krea-2-turbo", "seedream-v5-lite"]\n    client = VeniceImageClient()\n    available = await client.available_image_models(ttl_seconds=30)\n    if available is not None:\n        missing = [model for model in models if model not in available]\n        if missing:\n            raise RuntimeError(\n                "LIVE_KREA_SMOKE_FAILED stage=model_discovery "\n                f"missing_models={missing}"\n            )\n''',
    "live gate models",
)
gate = replace_once(
    gate,
    '''    correction_codes: list[str] = []\n    attempt_summaries: list[dict] = []\n\n    for attempt_index in range(2):\n        prompt = compiled.positive_prompt\n        if correction_codes:\n            prompt += corrective_prompt_for_reasons(\n                correction_codes,\n                expected_subject_count=expected_subject_count,\n                expected_interaction=plan.composition.get("interaction"),\n                secondary_subject_role=plan.composition.get("secondary_subject_role"),\n                identity_requirements=plan.identity.get("descriptor"),\n                photo_contract=requirements.get("photo_contract") or {},\n            )\n        seed = _safe_attempt_seed(base_seed, attempt_index)\n        result = await client.generate(\n            prompt,\n            compiled.negative_prompt,\n            width=int(compiled.provider_parameters["width"]),\n            height=int(compiled.provider_parameters["height"]),\n            seed=seed,\n            model=model,\n        )\n''',
    '''    correction_codes: list[str] = []\n    attempt_summaries: list[dict] = []\n    stable_krea_seed = _safe_attempt_seed(base_seed, 0)\n    attempt_plan = [\n        ("krea-2-turbo", 0),\n        ("krea-2-turbo", 1),\n        ("seedream-v5-lite", 0),\n    ]\n\n    for attempt_index, (model, correction_round) in enumerate(attempt_plan):\n        if correction_round and not correction_codes:\n            continue\n        prompt = compiled.positive_prompt\n        if correction_codes:\n            prompt += corrective_prompt_for_reasons(\n                correction_codes,\n                expected_subject_count=expected_subject_count,\n                expected_interaction=plan.composition.get("interaction"),\n                secondary_subject_role=plan.composition.get("secondary_subject_role"),\n                identity_requirements=plan.identity.get("descriptor"),\n                photo_contract=requirements.get("photo_contract") or {},\n            )\n        seed = stable_krea_seed if model == "krea-2-turbo" else _safe_attempt_seed(base_seed, attempt_index)\n        try:\n            result = await client.generate(\n                prompt,\n                compiled.negative_prompt,\n                width=int(compiled.provider_parameters["width"]),\n                height=int(compiled.provider_parameters["height"]),\n                seed=seed,\n                model=model,\n            )\n        except Exception as exc:\n            attempt_summaries.append({\n                "attempt": attempt_index + 1,\n                "model": model,\n                "provider": "error",\n                "error_type": type(exc).__name__,\n            })\n            correction_codes = []\n            continue\n''',
    "live gate attempt plan",
)
gate = gate.replace('                    "attempt": attempt_index + 1,\n                    "provider": "moderation_artifact",', '                    "attempt": attempt_index + 1,\n                    "model": model,\n                    "seed": seed,\n                    "provider": "moderation_artifact",')
gate = gate.replace('            correction_codes = ["requested_nudity_missing"]\n            continue', '            correction_codes = []\n            continue')
gate = gate.replace('                    "attempt": attempt_index + 1,\n                    "provider": "image",\n                    "qa": "failed",', '                    "attempt": attempt_index + 1,\n                    "model": model,\n                    "seed": seed,\n                    "provider": "image",\n                    "qa": "failed",')
gate = gate.replace('                    "attempt": attempt_index + 1,\n                    "provider": "image",\n                    "qa": "passed",\n                    "anatomy": "passed",', '                    "attempt": attempt_index + 1,\n                    "model": model,\n                    "seed": seed,\n                    "provider": "image",\n                    "qa": "passed",\n                    "anatomy": "passed",')
gate = gate.replace('                f"model={model} attempts={attempt_index + 1} summaries={attempt_summaries}",', '                f"final_model={model} attempts={attempt_index + 1} summaries={attempt_summaries}",')
gate = gate.replace('                "attempt": attempt_index + 1,\n                "provider": "image",\n                "qa": "passed",\n                "anatomy": "failed",', '                "attempt": attempt_index + 1,\n                "model": model,\n                "seed": seed,\n                "provider": "image",\n                "qa": "passed",\n                "anatomy": "failed",')
gate = gate.replace('        f"model={model} summaries={attempt_summaries}"', '        f"models={models} summaries={attempt_summaries}"')
gate_path.write_text(gate, encoding="utf-8")


# 7) Static gate-contract regression.
Path("tests/test_adult_generation_policy_contract.py").write_text(
    '''from pathlib import Path\n\n\ndef test_live_gate_uses_krea_same_seed_then_seedream_only():\n    source = Path("conftest.py").read_text(encoding="utf-8")\n    assert '("krea-2-turbo", 0)' in source\n    assert '("krea-2-turbo", 1)' in source\n    assert '("seedream-v5-lite", 0)' in source\n    assert 'stable_krea_seed if model == "krea-2-turbo"' in source\n    assert "lustify-sdxl" not in source\n    assert "lustify-v8" not in source\n''',
    encoding="utf-8",
)
